def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n or (n == 0 and not fields):
        if i >= n:
            # End of line: add current field
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        if i < n and line[i] != ',':
                            # Closing quote not followed by comma or end
                            return None
                        if i < n:
                            i += 1  # Skip comma
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1
            if i < n:
                i += 1  # Skip comma
            fields.append(field)

    return fields

